<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { ElButton,ElSelect,ElOption,ElInput,ElTag,ElDialog,ElCheckbox,ElAlert } from 'element-plus'
import { API } from '../../../shared/api'
import { dateLabel,isCancelled } from '../../../shared/console'
const props=defineProps<{api:API}>(),emit=defineEmits<{changed:[];open:[page:string]}>()
const rows=ref<any[]>([]),status=ref('all'),selected=ref<any>(null),source=ref<any>(null),error=ref(''),busy=ref(false),confirm=ref(false),checked=ref(false),action=ref('approve')
const linkClaim=ref(false),predicate=ref('residence'),value=ref(''),scope=ref('{}')
const originalContent=ref('')
const slots=['residence','occupation','school','response_language','response_detail','diet','work_habit','hobby','learning_goal','project_goal','time_preference','budget']
const reasons:Record<string,string>={model_supported_low_risk:'原话支持且风险较低，已由模型批准',not_supported_or_not_durable:'原话不支持或不值得长期保存',insufficient_support:'证据尚不足',sensitive_credential:'包含敏感凭据，不作为记忆保存',sensitive_personal_fact:'敏感个人事实，需人工确认',third_party_or_mixed_subject:'可能涉及他人或混合主体',complex_condition:'适用条件较复杂',temporal_or_transition_requires_review:'涉及历史或状态变化，需要核对时间和版本',plan_or_hypothesis:'计划或假设不能直接当成已成立事实',unbound_negation:'否定含义需要核对',quote_not_unique_or_missing:'引用未能唯一定位',model_unavailable:'模型尚未配置就绪',model_or_publish_failed:'模型或入库失败，候选已保留',source_or_candidate_changed:'来源或候选发生变化，未自动写入',existing_state_requires_revision:'与已有状态冲突，需要明确纠正或变化',semantic_paraphrase_supported:'改写已通过LLM语义核验',source_too_long:'完整来源超出本次审核预算'}
let alive=true,timer:ReturnType<typeof setInterval>|undefined
function label(item:any){return item.status==='approved'?(item.assessment?.reviewer==='llm'?'LLM已入库':'已批准'):item.status==='rejected'?'已拒绝':item.status==='applying'?'处理中':item.assessment?'需人工辅助':'等待处理'}
async function load(){busy.value=true;try{const next=await props.api.request('/memory-reviews?limit=500&status='+status.value,undefined,'GET','review-list');if(!alive)return;const changed=JSON.stringify(rows.value)!==JSON.stringify(next);rows.value=next;const fresh=rows.value.find(r=>r.id===selected.value?.id);if(fresh&&selected.value?.content===originalContent.value){selected.value={...fresh};originalContent.value=fresh.content}if(changed)emit('changed')}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
async function inspect(item:any){selected.value={...item};originalContent.value=item.content;source.value=null;checked.value=false;linkClaim.value=false;value.value='';scope.value='{}';error.value='';try{const result=await props.api.request('/claim-source/'+encodeURIComponent(item.source_ref),undefined,'GET','review-source');if(alive&&selected.value?.id===item.id)source.value=result}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}}
async function autoReview(){if(!selected.value)return;busy.value=true;error.value='';try{const row=await props.api.request('/memory-reviews/'+encodeURIComponent(selected.value.id)+'/auto-review',{content:selected.value.content,kind:selected.value.kind,importance:selected.value.importance});if(alive){selected.value=row;await load()}}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
function propose(kind:string){action.value=kind;checked.value=false;confirm.value=true;error.value=''}
async function apply(){if(!checked.value||!selected.value)return;busy.value=true;try{const item=selected.value;if(action.value==='approve'&&!source.value?.personal_claim_eligible)throw new Error('请先核对可用的本人来源');const payload:any=action.value==='approve'?{content:item.content,kind:item.kind,importance:item.importance}:{};if(action.value==='approve'&&linkClaim.value){if(!value.value.trim())throw new Error('请填写并核对结构化值');payload.approve_claim=true;payload.claim={predicate:predicate.value,value:value.value.trim(),scope:JSON.parse(scope.value),evidence:[source.value.evidence],condition_evidence:Object.keys(JSON.parse(scope.value)).length?[source.value.evidence]:[],reason:'用户在候选审核中核对原话及结构化字段后明确批准'}}await props.api.request('/memory-reviews/'+encodeURIComponent(item.id)+'/'+action.value,payload);confirm.value=false;selected.value=null;source.value=null;await load()}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)busy.value=false}}
onMounted(()=>{void load();timer=setInterval(()=>{if(!busy.value&&!confirm.value&&(!selected.value||selected.value.content===originalContent.value))void load()},5000)})
onUnmounted(()=>{alive=false;clearInterval(timer)})
</script>
<template>
<el-alert v-if="error" :title="error" type="error" :closable="false"/>
<section class="panel"><h2>模型审核为主，人工处理例外</h2><p>默认策略：日常聊天完成后自动抽取，LLM核对原话和长期价值，低风险候选自动入库；来源、主体、条件、敏感信息或已有状态冲突时保留人工辅助。这里同时展示自动决定与待处理项。</p><el-button @click="emit('open','pipeline')">查看当前审核策略与任务</el-button><el-button @click="emit('open','memories')">查看长期记忆库</el-button></section>
<div class="explorer-grid"><section class="panel"><div class="section-title"><h2>候选与审核记录</h2><el-button :loading="busy" @click="load">刷新</el-button></div><el-select v-model="status" @change="load" aria-label="候选状态"><el-option value="all" label="全部记录"/><el-option value="pending" label="待处理 / 人工辅助"/><el-option value="approved" label="已入库"/><el-option value="rejected" label="已拒绝"/></el-select><p>最多载入500条；自动批准也保留模型、原因、用量和来源记录。</p><button v-for="item in rows" :key="item.id" class="claim-row" :class="{chosen:selected?.id===item.id}" @click="inspect(item)"><div><span>{{ item.kind }}</span><small>{{ item.job_id?.startsWith('manual:')?'手动提出':'自动抽取' }}</small><el-tag size="small" :type="item.status==='approved'?'success':item.status==='pending'?'warning':'info'">{{ label(item) }}</el-tag></div><strong>{{ item.content }}</strong><small>{{ dateLabel(item.created_at,true) }}</small></button><div v-if="busy&&!rows.length" class="empty" role="status">正在读取候选…</div><div v-else-if="!rows.length" class="empty"><h3>没有符合条件的记录</h3><p>公开导入资料不属于本人事实；临时提问也不必形成长期记忆。可以从本人原话发起一次LLM提取。</p><el-button @click="emit('open','conversations')">从历史原话开始</el-button></div></section>
<section class="panel"><template v-if="selected"><div class="section-title"><h2>证据与决定</h2><el-tag>{{ label(selected) }}</el-tag></div><el-input v-model="selected.content" type="textarea" :rows="4" maxlength="4000" :disabled="selected.status!=='pending'||busy"/><h3>对应原始来源</h3><div v-if="source" class="source-original">{{ source.content }}</div><p v-else>正在读取来源，或来源已不可用。</p><el-alert v-if="source&&!source.personal_claim_eligible" title="这条原话不能作为本人记忆依据。" type="warning" :closable="false"/>
<div v-if="selected.assessment" class="info-note"><strong>{{ selected.assessment.reviewer==='llm'?'LLM审核记录':'规则或联合语义审核记录' }}</strong><p>{{ selected.assessment.model||'未发起模型调用' }} · {{ selected.assessment.assessment }}</p><p v-for="code in selected.assessment.reason_codes" :key="code">{{ reasons[code]||code }}</p><details><summary>查看策略与用量</summary><pre>{{ JSON.stringify(selected.assessment,null,2) }}</pre></details></div>
<div v-if="selected.status==='pending'"><div class="actions"><el-button type="primary" :loading="busy" :disabled="busy||!source?.personal_claim_eligible" @click="autoReview">LLM审核并尝试入库</el-button><el-button :disabled="busy" @click="propose('reject')">拒绝候选</el-button></div><p>此按钮会调用已配置模型，可能产生费用；未通过不会强制写入。编辑后的内容会重新审核。</p><details><summary>人工辅助：手动确认或核对结构化字段</summary><el-checkbox v-model="linkClaim">同时核对并批准结构化状态</el-checkbox><div v-if="linkClaim" class="form-grid"><label>属性<el-select v-model="predicate"><el-option v-for="slot in slots" :key="slot" :value="slot" :label="slot"/></el-select></label><label>简短结构化值（例如杭州、慢跑）<el-input v-model="value" maxlength="500"/></label><label>适用条件 JSON<el-input v-model="scope" maxlength="2000"/></label><p>不要把整句候选填入值。忠实改写可由LLM语义核验；主体、条件、时间或冲突疑问仍需解决。取消联动可仅保存普通记忆。</p></div><el-button :disabled="busy||!source?.personal_claim_eligible" @click="propose('approve')">核对后写入长期记忆</el-button></details></div>
<div v-else-if="selected.status==='approved'" class="actions"><el-button type="primary" @click="emit('open','memories')">到长期记忆库查看</el-button></div></template><div v-else class="empty"><h3>选择记录查看证据与决定</h3><p>自动入库与人工辅助都会留下可追溯记录。</p></div></section></div>
<el-dialog v-model="confirm" :title="action==='approve'?'人工确认写入长期记忆':'确认拒绝候选'" width="min(500px,94vw)"><p>{{ selected?.content }}</p><p v-if="action==='approve'&&linkClaim">同时批准：{{ predicate }} = {{ value }}；条件 {{ scope }}。值为改写时可能调用LLM语义核验。</p><el-checkbox v-model="checked">我已核对原话，确认执行此操作</el-checkbox><template #footer><el-button @click="confirm=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!checked" @click="apply">确认处理</el-button></template></el-dialog>
</template>
